class query_factory {
    ContextBinding binding_;

public:
    explicit query_factory(UserContext& user_context) : binding_(user_context) {}

    StatusRequest<false> statusesMinimal() const {
        return StatusRequest<false>(binding_.get(), true);
    }

    StatusRequest<false> statuses() const {
        return StatusRequest<false>(binding_.get());
    }

    StatusRequest<false> statusesWithChildren() const {
        return StatusRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }

    CategoryRequest<false> categoriesMinimal() const {
        return CategoryRequest<false>(binding_.get(), true);
    }

    CategoryRequest<false> categories() const {
        return CategoryRequest<false>(binding_.get());
    }

    CategoryRequest<false> categoriesWithChildren() const {
        return CategoryRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }

    PlatformRequest<false> platformsMinimal() const {
        return PlatformRequest<false>(binding_.get(), true);
    }

    PlatformRequest<false> platforms() const {
        return PlatformRequest<false>(binding_.get());
    }

    PlatformRequest<false> platformsWithChildren() const {
        return PlatformRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }
};
